 @Override public void onLocationChanged(Location l){if(l.hasAccuracy()&&l.getAccuracy()>100)return;if(loc!=null&&l.getTime()<loc.getTime())return;boolean first=loc==null;loc=l;GeoPoint p=gp(l);if(car==null){car=new Marker(map);car.setTitle("Sua localização");car.setAnchor(Marker.ANCHOR_CENTER,Marker.ANCHOR_CENTER);map.getOverlays().add(car);}car.setPosition(p);if(car!=null&&first)car.setIcon(symbol("↑",0xff087e65));if(first){map.getController().setZoom(15.0);map.getController().animateTo(p);refresh();refreshTraffic();if(destination!=null)calculate();}if(driving){map.getController().animateTo(p);progress();}speed.setText(l.hasSpeed()?String.format(Locale.US,"%.0f km/h",l.getSpeed()*3.6):"Velocidade indisponível");map.invalidate();}
