 String format(double m,double s){return String.format(Locale.US,"%.1f km · %d min",m/1000,(int)Math.ceil(s/60));}
 void say(String s){if(sound&&voiceReady)tts.speak(s,TextToSpeech.QUEUE_ADD,null,UUID.randomUUID().toString());}
 void alarm(String k,String text){if(!sound)return;if(tone!=null)tone.startTone(k.equals("radar")?ToneGenerator.TONE_CDMA_ALERT_CALL_GUARD:k.equals("lombada")?ToneGenerator.TONE_PROP_BEEP2:ToneGenerator.TONE_PROP_BEEP,260);main.postDelayed(()->say(text),300);}
 static double[] project(GeoPoint p,ArrayList<GeoPoint> line){double total=0,best=Double.MAX_VALUE,along=0,bearing=0;double scale=Math.cos(Math.toRadians(p.getLatitude()));for(int i=1;i<line.size();i++){GeoPoint a=line.get(i-1),b=line.get(i);double dx=(b.getLongitude()-a.getLongitude())*scale,dy=b.getLatitude()-a.getLatitude();double t=Math.max(0,Math.min(1,((p.getLongitude()-a.getLongitude())*scale*dx+(p.getLatitude()-a.getLatitude())*dy)/(dx*dx+dy*dy+1e-20)));double len=a.distanceToAsDouble(b);double dist=p.distanceToAsDouble(new GeoPoint(a.getLatitude()+t*dy,a.getLongitude()+t*(b.getLongitude()-a.getLongitude())));if(dist<best){best=dist;along=total+t*len;bearing=(Math.toDegrees(Math.atan2(dx,dy))+360)%360;}total+=len;}return new double[]{along,best,total,bearing};}
 void progress(){if(loc==null||routes.isEmpty()||destination==null)return;Route r=routes.get(selected);GeoPoint p=gp(loc);double[] pos=project(p,r.points);double remain=Math.max(0,r.meters*(1-pos[0]/Math.max(1,pos[2])));double sec=r.seconds*remain/Math.max(1,r.meters);summary.setText(format(remain,sec)+" · "+new java.text.SimpleDateFormat("HH:mm",new Locale("pt","BR")).format(new Date(System.currentTimeMillis()+(long)(sec*1000))));if(!stops.isEmpty()&&p.distanceToAsDouble(stops.get(0).p)<35){stops.remove(0);say("Parada alcançada");calculate();return;}if(stops.isEmpty()&&p.distanceToAsDouble(destination.p)<25){driving=false;say("Você chegou ao destino");nav.setVisibility(View.GONE);renderRoute();return;}if(pos[1]>100&&System.currentTimeMillis()-lastReroute>30000){lastReroute=System.currentTimeMillis();say("Recalculando rota");calculate();return;}
 while(stepIndex<r.steps.size()-1&&project(r.steps.get(stepIndex).p,r.points)[0]<pos[0]-10)stepIndex++;if(stepIndex<r.steps.size()){Step s=r.steps.get(stepIndex);double d=Math.max(0,project(s.p,r.points)[0]-pos[0]);nav.setText(s.text+" · "+Math.round(d)+" m");if(d<250&&warned.add("step"+stepIndex))say("Em "+Math.round(d)+" metros, "+s.text);}
 showUpcoming(p,r,pos);warnJam(r,pos,p);if(mode.equals("walk")||pos[1]>65||System.currentTimeMillis()-lastWarn<4500)return;ArrayList<Event> all=new ArrayList<>(fixed);all.addAll(live);Event chosen=null;double nearest=Double.MAX_VALUE;String stage="";for(Event e:all){if(e.expires<System.currentTimeMillis()||e.kind.equals("semaforo")||e.kind.equals("historico"))continue;double max=e.kind.equals("radar")?1000:e.kind.equals("lombada")?220:350;if(p.distanceToAsDouble(e.p)>max+60)continue;double[] v=project(e.p,r.points);double d=v[0]-pos[0];if(v[1]>40||d<0||d>max)continue;if(!Double.isNaN(e.direction)&&Math.abs((v[3]-e.direction+540)%360-180)>65)continue;String k=e.id+(e.kind.equals("radar")?(d>500?":1000":d>250?":500":":250"):":near");if(warned.contains(k))continue;if(d<nearest){chosen=e;nearest=d;stage=k;}}if(chosen!=null){warned.add(stage);lastWarn=System.currentTimeMillis();alarm(chosen.kind,chosen.label+" a "+Math.round(nearest/10)*10+" metros"+(chosen.limit>0?". Limite informado: "+(int)chosen.limit+" quilômetros por hora.":"."));}}
 void settings(){String[] opts={"Sons: "+(sound?"ligados":"desligados"),"Semáforos: espera estimada pelo histórico local, sem previsão da luz verde","Ônibus: dados pendentes","Preços de combustível: pendentes","Evitar morros e riscos: pendentes","Fontes: OpenStreetMap, Pardal, Waze municipal"};new AlertDialog.Builder(this).setTitle("Configurações e cobertura").setItems(opts,(d,i)->{if(i==0){sound=!sound;if(!sound&&tts!=null)tts.stop();}else toast(opts[i]);}).setPositiveButton("Fechar",null).show();}

 void refresh(){if(loc==null||fetching)return;GeoPoint p=gp(loc);if(catalogAt!=null&&catalogAt.distanceToAsDouble(p)<5000&&System.currentTimeMillis()-lastCatalog<3600000)return;fetching=true;pool.execute(()->{ArrayList<Event> f=new ArrayList<>();boolean ok=false;try{JSONObject states=new JSONObject(get("https://raw.githubusercontent.com/Murkiriel/pardal/main/catalogo.json")).getJSONObject("ufs");Iterator<String> it=states.keys();while(it.hasNext()){String uf=it.next();if(uf.equals("BR"))continue;JSONObject u=states.getJSONObject(uf);JSONArray bb=u.optJSONArray("bbox");if(bb==null||p.getLatitude()<bb.getDouble(0)-.3||p.getLatitude()>bb.getDouble(2)+.3||p.getLongitude()<bb.getDouble(1)-.3||p.getLongitude()>bb.getDouble(3)+.3)continue;try{loadCatalog(uf,p,f);ok=true;}catch(Exception ignored){}}}catch(Exception ignored){}
 try{loadOsm(p,f);ok=true;}catch(Exception ignored){}try{loadAntt(p,f);ok=true;}catch(Exception ignored){}try{loadCariacica(p,f);}catch(Exception ignored){}
 boolean done=ok;main.post(()->{fetching=false;if(done&&!f.isEmpty()){ArrayList<Event> combined=new ArrayList<>(f);for(Event old:fixed)if(old.p.distanceToAsDouble(p)<65000)mergeEvent(combined,old);fixed=combined;catalogAt=p;lastCatalog=System.currentTimeMillis();}updateCoverage();drawEvents();});});}
 String trafficBase(int id){return "https://gis.vitoria.es.gov.br/arcgis/rest/services/Opendata/DadosAbertos/MapServer/"+id+"/query?where=1%3D1&returnGeometry=true&outSR=4326&resultRecordCount=1000&f=json&outFields=";}
 boolean trafficArea(GeoPoint p){return p.getLatitude()>-20.7&&p.getLatitude()<-19.9&&p.getLongitude()>-40.9&&p.getLongitude()<-39.95;}
 void refreshTraffic(){if(loc==null||fetchingTraffic)return;GeoPoint p=gp(loc);if(!trafficArea(p)){jams.clear();live.clear();jamFeedOk=false;alertFeedOk=false;updateCoverage();drawJams();drawEvents();return;}fetchingTraffic=true;pool.execute(()->{ArrayList<Jam> j=new ArrayList<>();ArrayList<Event> l=new ArrayList<>();boolean jo=false,ao=false;long now=System.currentTimeMillis();
 try{JSONArray rows=new JSONObject(get(trafficBase(26)+"uuid,street,jam_level,jam_speedkmh,delay,pubmillis")).getJSONArray("features");for(int i=0;i<rows.length();i++){try{JSONObject o=rows.getJSONObject(i),at=o.getJSONObject("attributes");long stamp=at.optLong("pubmillis",0);if(stamp<=0||stamp>now+60000||now-stamp>900000)continue;JSONArray paths=o.getJSONObject("geometry").getJSONArray("paths");for(int k=0;k<paths.length();k++){JSONArray path=paths.getJSONArray(k);Jam z=new Jam();z.id=at.optString("uuid")+":"+k;z.street=at.optString("street","");z.level=at.optInt("jam_level",0);z.speed=at.optDouble("jam_speedkmh",-1);z.delay=at.optDouble("delay",-1);z.expires=stamp+900000;for(int n=0;n<path.length();n++){JSONArray pair=path.getJSONArray(n);z.points.add(new GeoPoint(pair.getDouble(1),pair.getDouble(0)));}if(z.points.size()>1&&z.level>0&&z.level<=5)j.add(z);}}catch(Exception ignored){}}jo=true;}catch(Exception ignored){}
 try{JSONArray rows=new JSONObject(get(trafficBase(25)+"uuid,street,alert_type,alert_subtype,pubmillis")).getJSONArray("features");for(int i=0;i<rows.length();i++){try{JSONObject o=rows.getJSONObject(i),at=o.getJSONObject("attributes"),g=o.getJSONObject("geometry");long stamp=at.optLong("pubmillis",0);if(stamp<=0||stamp>now+60000||now-stamp>900000)continue;String t=at.optString("alert_type").toUpperCase(Locale.ROOT),sub=at.optString("alert_subtype").toUpperCase(Locale.ROOT);String kind=sub.contains("POT_HOLE")?"buraco":sub.contains("CONSTRUCTION")?"obra":sub.contains("LANE_CLOSED")||t.contains("ROAD_CLOSED")?"interdicao":sub.contains("CAR_STOPPED")?"veiculo":sub.contains("FLOOD")?"alagamento":sub.contains("JAM")||t.equals("JAM")?"transito":t.contains("ACCIDENT")?"acidente":t.contains("CAMERA")?"radar":"perigo";String label=kind.equals("buraco")?"Buraco na via":kind.equals("obra")?"Obra na via":kind.equals("interdicao")?"Interdição reportada":kind.equals("veiculo")?"Veículo parado":kind.equals("alagamento")?"Alagamento reportado":kind.equals("transito")?"Trânsito intenso reportado":kind.equals("acidente")?"Acidente reportado":kind.equals("radar")?"Radar reportado":"Perigo reportado";Event e=new Event("waze"+at.optString("uuid"),kind,label,"Waze · Prefeitura de Vitória",g.getDouble("y"),g.getDouble("x"));e.expires=stamp+900000;l.add(e);}catch(Exception ignored){}}ao=true;}catch(Exception ignored){}
 boolean jamOk=jo,alertsOk=ao;main.post(()->{fetchingTraffic=false;jamFeedOk=jamOk;alertFeedOk=alertsOk;if(jamOk)jams=j;else jams.removeIf(x->x.expires<System.currentTimeMillis());if(alertsOk)live=l;else live.removeIf(x->x.expires<System.currentTimeMillis());if(jamOk||alertsOk)trafficUpdated=System.currentTimeMillis();updateCoverage();drawJams();drawEvents();});});}
 void updateCoverage(){long rad=fixed.stream().filter(e->e.kind.equals("radar")).count(),bumps=fixed.stream().filter(e->e.kind.equals("lombada")).count();String info=jamFeedOk?"Vitória: "+jams.size()+" trechos de trânsito reportados":"Trânsito ao vivo: fonte indisponível ou fora da cobertura";coverage.setText(rad+" radares · "+bumps+" lombadas\n"+info+(alertFeedOk?" · "+live.size()+" ocorrências":""));}
 void drawJams(){map.getOverlays().removeAll(jamOverlays);jamOverlays.clear();long now=System.currentTimeMillis();for(Jam j:jams){if(j.expires<now)continue;Polyline line=new Polyline();line.setPoints(j.points);line.getOutlinePaint().setColor(j.level>=5?0xff851b45:j.level>=4?0xffe53935:j.level==3?0xfff17b19:j.level==2?0xffedb829:0xff60aa76);line.getOutlinePaint().setStrokeWidth(dp(7));line.setTitle(j.street);line.setSnippet((j.level>=5?"Trânsito parado":j.level>=4?"Trânsito intenso":j.level==3?"Trânsito moderado":"Trânsito leve")+(j.speed>=0?" · "+Math.round(j.speed)+" km/h":"")+" · Waze / Vitória");line.setOnClickListener((o,m,point)->{toast(line.getTitle()+"\n"+line.getSnippet());return true;});map.getOverlays().add(line);jamOverlays.add(line);}map.invalidate();}
 void warnJam(Route r,double[] pos,GeoPoint p){if(mode.equals("walk")||pos[1]>40)return;for(Jam j:jams){if(j.expires<System.currentTimeMillis()||j.level<3||warned.contains("jam"+j.id))continue;double near=Double.MAX_VALUE;for(int i=1;i<j.points.size();i++){GeoPoint a=j.points.get(i-1),b=j.points.get(i);if(a.distanceToAsDouble(p)>1400&&b.distanceToAsDouble(p)>1400)continue;double[] q=project(a,r.points);double delta=q[0]-pos[0];if(q[1]>35||delta<0||delta>700)continue;double bearing=(a.bearingTo(b)+360)%360;if(Math.abs((bearing-q[3]+540)%360-180)>70)continue;near=Math.min(near,delta);}if(near<700&&System.currentTimeMillis()-lastWarn>4500){warned.add("jam"+j.id);lastWarn=System.currentTimeMillis();alarm("transito",(j.level>=5?"Trânsito parado":j.level>=4?"Trânsito intenso":"Trânsito moderado")+" a "+Math.round(near/10)*10+" metros");return;}}}
 void loadCatalog(String uf,GeoPoint p,ArrayList<Event> out)throws Exception{String base="https://raw.githubusercontent.com/Murkiriel/pardal/main/estados/"+uf+"/";JSONArray fs=new JSONObject(get(base+"radares.geojson")).getJSONArray("features");for(int i=0;i<fs.length();i++){JSONObject f=fs.getJSONObject(i),a=f.getJSONObject("properties");GeoPoint g=coord(f.getJSONObject("geometry").getJSONArray("coordinates"));boolean active=a.optBoolean("active");if(!active&&!(uf.equals("ES")&&g.getLatitude()>-20.34&&g.getLatitude()<-19.98&&g.getLongitude()>-40.49&&g.getLongitude()<-40.15))continue;if(g.distanceToAsDouble(p)>65000)continue;Event e=new Event("radar"+g.getLatitude()+":"+g.getLongitude()+":"+a.optString("direction_deg"),active?"radar":"historico",!active?"Cadastro histórico · situação não confirmada":a.optString("kind").equals("RED_LIGHT")?"Radar de avanço de sinal":a.optString("kind").equals("SECTION")?"Radar por trecho":"Radar de velocidade","Pardal · "+a.optString("source"),g.getLatitude(),g.getLongitude());e.limit=a.optDouble("limit_kmh",0);e.direction=a.optDouble("direction_deg",Double.NaN);out.add(e);}try{String[] rows=get(base+"lombadas.csv").split("\\r?\\n");for(int i=1;i<rows.length;i++){String[] a=rows[i].split(",");if(a.length<3)continue;double lat=Double.parseDouble(a[0]),lon=Double.parseDouble(a[1]);if(new GeoPoint(lat,lon).distanceToAsDouble(p)>25000)continue;out.add(new Event("bump"+lat+":"+lon,"lombada","Atenção, lombada","Pardal · OSM",lat,lon));}}catch(Exception ignored){}}
 void drawEvents(){map.getOverlays().removeAll(eventOverlays);eventOverlays.clear();ArrayList<Event> all=new ArrayList<>(fixed);all.addAll(live);GeoPoint here=loc==null?null:gp(loc);for(Event e:all){if(here==null||e.p.distanceToAsDouble(here)>12000||e.expires<System.currentTimeMillis())continue;if(e.kind.equals("lombada")&&map.getZoomLevelDouble()<14)continue;if(eventOverlays.size()>1600&&!e.kind.equals("radar")&&!e.kind.equals("semaforo"))continue;Marker m=new Marker(map);m.setPosition(e.p);m.setTitle(e.label+(e.limit>0?" · "+(int)e.limit+" km/h":""));m.setSnippet(e.source);m.setIcon(e.kind.equals("radar")?symbol(e.label.contains("sinal")?"S":e.limit>0?String.valueOf((int)e.limit):"R",0xffc63831):e.kind.equals("semaforo")?trafficIcon():symbol(e.kind.equals("lombada")?"∩":e.kind.equals("historico")?"?":"!",e.kind.equals("lombada")?0xff7e4aa4:e.kind.equals("historico")?0xff68727e:0xffe38a24));m.setAnchor(Marker.ANCHOR_CENTER,Marker.ANCHOR_CENTER);map.getOverlays().add(m);eventOverlays.add(m);}map.invalidate();}

 void themeDialog(){String[] labels={"Automático","Claro","Escuro"};new AlertDialog.Builder(this).setTitle("Tema do Rota Única").setSingleChoiceItems(labels,theme.equals("dark")?2:theme.equals("light")?1:0,(d,i)->{theme=i==2?"dark":i==1?"light":"auto";getPreferences(0).edit().putString("theme",theme).apply();applyTheme();d.dismiss();}).setNegativeButton("Fechar",null).show();}
 void applyTheme(){dark=theme.equals("dark")||(theme.equals("auto")&&(getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES);paper=dark?0xff202631:0xfff8faf9;ink=dark?0xfff1f5f4:INK;chip=dark?0xff30483f:0xffe4f3ec;bar.setBackground(bg(paper,26));bottom.setBackground(bg(paper,28));results.setBackground(bg(paper,20));search.setTextColor(ink);search.setHintTextColor(dark?0xffaab9b5:0xff69796f);radarBanner.setBackground(bg(dark?0xff492c32:0xffffe5e5,18));signalBanner.setBackground(bg(dark?0xff333e49:0xffe8eff0,18));recolor(top);recolor(bottom);nav.setTextColor(Color.WHITE);nav.setBackground(bg(0xff087e65,22));getWindow().setStatusBarColor(paper);getWindow().setNavigationBarColor(paper);getWindow().getDecorView().setSystemUiVisibility(dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);map.getOverlayManager().getTilesOverlay().setColorFilter(dark?org.osmdroid.views.overlay.TilesOverlay.INVERT_COLORS:null);map.invalidate();renderRoute();}
 void recolor(View v){if(v instanceof Button){Button b=(Button)v;b.setTextColor(dark?0xffc5f8e6:0xff075e49);b.setBackground(bg(chip,22));}else if(v instanceof TextView)((TextView)v).setTextColor(ink);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)recolor(g.getChildAt(i));}}
 android.graphics.drawable.Drawable symbol(String label,int color){int n=dp(32);android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(n,n,android.graphics.Bitmap.Config.ARGB_8888);android.graphics.Canvas c=new android.graphics.Canvas(b);android.graphics.Paint p=new android.graphics.Paint(3);p.setColor(Color.WHITE);c.drawCircle(n/2f,n/2f,n/2f-1,p);p.setColor(color);c.drawCircle(n/2f,n/2f,n/2f-dp(2),p);p.setColor(Color.WHITE);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextSize(dp(label.length()>1?12:16));p.setTextAlign(android.graphics.Paint.Align.CENTER);c.drawText(label,n/2f,n/2f-(p.ascent()+p.descent())/2,p);return new android.graphics.drawable.BitmapDrawable(getResources(),b);}
 android.graphics.drawable.Drawable trafficIcon(){int w=dp(22),h=dp(37);android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(w,h,android.graphics.Bitmap.Config.ARGB_8888);android.graphics.Canvas c=new android.graphics.Canvas(b);android.graphics.Paint p=new android.graphics.Paint(3);p.setColor(0xff202631);c.drawRoundRect(0,0,w,h,dp(6),dp(6),p);int[] colors={0xffde6b68,0xffe8c169,0xff6bad94};for(int i=0;i<3;i++){p.setColor(colors[i]);c.drawCircle(w/2f,dp(8+i*10),dp(4),p);}return new android.graphics.drawable.BitmapDrawable(getResources(),b);}
 void showUpcoming(GeoPoint p,Route r,double[] pos){Event radar=null,signal=null;double rd=1001,sd=501;for(Event e:fixed){if(e.p.distanceToAsDouble(p)>1100)continue;if(!e.kind.equals("radar")&&!e.kind.equals("semaforo"))continue;double[] z=project(e.p,r.points);double d=z[0]-pos[0];if(z[1]>40||d<0)continue;if(!Double.isNaN(e.direction)&&Math.abs((z[3]-e.direction+540)%360-180)>65)continue;if(e.kind.equals("radar")&&d<rd){radar=e;rd=d;}if(e.kind.equals("semaforo")&&d<sd){signal=e;sd=d;}}radarBanner.setVisibility(radar==null||mode.equals("walk")?View.GONE:View.VISIBLE);if(radar!=null)radarBanner.setText(radar.label+" · "+Math.round(rd)+" m"+(radar.limit>0?" · "+(int)radar.limit+" km/h":""));observeDelay(p,r,pos,signal,sd);if(signal==null||pos[1]>40||mode.equals("walk")){clearSignalWait();return;}String key=delayBucket(signal,project(signal.p,r.points)[3]);if(!signal.id.equals(waitSignalId)){waitStart=0;waitSignalId=signal.id;}if(!key.equals(currentDelayKey)){currentDelayKey=key;currentDelays=readDelays(key);}signalDistance=sd;signalStopCandidate=loc!=null&&loc.hasSpeed()&&loc.getSpeed()<=0.8&&loc.hasAccuracy()&&loc.getAccuracy()<=25&&sd<=65;if(signalStopCandidate){if(waitStart==0)waitStart=SystemClock.elapsedRealtime();}else waitStart=0;renderSignalWait();}
 void clearSignalWait(){waitSignalId=null;waitStart=0;signalStopCandidate=false;signalDistance=Double.NaN;currentDelayKey=null;currentDelays.clear();if(!driving)resetObservation();if(signalBanner!=null)signalBanner.setVisibility(View.GONE);}
 void renderSignalWait(){if(signalBanner==null)return;if(!driving||waitSignalId==null||loc==null||SystemClock.elapsedRealtimeNanos()-loc.getElapsedRealtimeNanos()>5000000000L){clearSignalWait();return;}signalBanner.setVisibility(View.VISIBLE);long seconds=waitStart>0?(SystemClock.elapsedRealtime()-waitStart)/1000:0;String text="Semáforo a "+Math.round(signalDistance)+" m · fase não disponível";if(signalStopCandidate&&seconds>=3)text+="\nParado próximo ao sinal: "+String.format(Locale.US,"%02d:%02d",seconds/60,seconds%60)+" (tempo decorrido)";if(signalStopCandidate&&seconds>=3){String estimate=estimateDelay(currentDelays,seconds);if(estimate!=null)text+="\nEspera restante estimada: "+estimate+" · histórico local";}signalBanner.setText(text);}
 String delayBucket(Event signal,double bearing){Calendar c=Calendar.getInstance(TimeZone.getTimeZone("America/Sao_Paulo"));int day=c.get(Calendar.DAY_OF_WEEK),hour=c.get(Calendar.HOUR_OF_DAY);int sector=(int)Math.floor((bearing+22.5)/45)%8;return signal.id+"_"+sector+"_"+((day==Calendar.SATURDAY||day==Calendar.SUNDAY)?"fim":"util")+"_"+hour+"_"+mode;}
 ArrayList<Long> readDelays(String key){ArrayList<Long> a=new ArrayList<>();try{JSONArray j=new JSONArray(getSharedPreferences("signal_delays",0).getString(key,"[]"));long now=System.currentTimeMillis();for(int i=0;i<j.length();i++){JSONArray v=j.getJSONArray(i);if(v.getLong(0)<=now&&now-v.getLong(0)<14L*86400000L)a.add(v.getLong(1));}}catch(Exception ignored){}return a;}
 void saveDelay(String key,long seconds){if(seconds<6||seconds>180)return;android.content.SharedPreferences prefs=getSharedPreferences("signal_delays",0);JSONArray out=new JSONArray();long now=System.currentTimeMillis();try{JSONArray j=new JSONArray(prefs.getString(key,"[]"));for(int i=Math.max(0,j.length()-29);i<j.length();i++){JSONArray v=j.getJSONArray(i);if(v.getLong(0)<=now&&now-v.getLong(0)<14L*86400000L)out.put(v);}}catch(Exception ignored){}JSONArray sample=new JSONArray();sample.put(now);sample.put(seconds);out.put(sample);prefs.edit().putString(key,out.toString()).apply();}
 String estimateDelay(ArrayList<Long> values,long elapsed){ArrayList<Long> remaining=new ArrayList<>();for(long v:values)if(v>elapsed)remaining.add(v-elapsed);if(values.size()<8||remaining.size()<5)return null;Collections.sort(remaining);long low=remaining.get((int)Math.floor((remaining.size()-1)*.20)),high=remaining.get((int)Math.ceil((remaining.size()-1)*.80));if(high-low>45)return null;low=Math.max(5,(low/5)*5);high=Math.max(low+5,((high+4)/5)*5);return low+"–"+high+" s";}
 void resetObservation(){delayKey=null;observedRoute=null;observedSignal=null;lastStopSample=0;lastStopDistance=0;}
 void observeDelay(GeoPoint p,Route r,double[] pos,Event signal,double sd){
 if(!driving||mode.equals("walk")||mode.equals("bus")||pos[1]>25||loc==null||!loc.hasAccuracy()||loc.getAccuracy()>12||!loc.hasSpeed()){resetObservation();return;}
 long now=SystemClock.elapsedRealtime();
 if(observedSignal!=null){double[] z=project(observedSignal,r.points);double d=z[0]-pos[0];if(observedRoute!=r||z[1]>25||now-lastStopSample>200000||d>lastStopDistance+18){resetObservation();}else if(d<-12){long elapsed=(now-lastStopSample)/1000;if(loc.getSpeed()>1.5&&p.distanceToAsDouble(observedSignal)<45)saveDelay(delayKey,elapsed);resetObservation();}else return;}
 if(signal!=null&&sd>=8&&sd<=35&&loc.getSpeed()<=.6){observedRoute=r;observedSignal=signal.p;delayKey=delayBucket(signal,project(signal.p,r.points)[3]);lastStopSample=now;lastStopDistance=sd;}
 }
 void mergeEvent(ArrayList<Event> out,Event e){for(Event old:out){if(!old.kind.equals(e.kind)||old.p.distanceToAsDouble(e.p)>22)continue;if(!Double.isNaN(old.direction)&&!Double.isNaN(e.direction)&&Math.abs((old.direction-e.direction+540)%360-180)>40)continue;if(old.limit<=0&&e.limit>0)old.limit=e.limit;if(e.label.contains("avanço"))old.label=e.label;if(!old.source.contains(e.source))old.source+=" + "+e.source;return;}out.add(e);}
 void loadOsm(GeoPoint p,ArrayList<Event> out)throws Exception{String q="[out:json][timeout:18];(node(around:15000,"+p.getLatitude()+","+p.getLongitude()+")[highway=traffic_signals];node(around:18000,"+p.getLatitude()+","+p.getLongitude()+")[highway=speed_camera];node(around:18000,"+p.getLatitude()+","+p.getLongitude()+")[enforcement];node(around:12000,"+p.getLatitude()+","+p.getLongitude()+")[traffic_calming~\"^(bump|hump|table|cushion|rumble_strip)$\"];way(around:12000,"+p.getLatitude()+","+p.getLongitude()+")[traffic_calming~\"^(bump|hump|table|cushion)$\"];);out center;";JSONObject data=null;for(String base:new String[]{"https://overpass-api.de/api/interpreter","https://overpass.kumi.systems/api/interpreter"}){try{data=new JSONObject(get(base+"?data="+enc(q)));break;}catch(Exception ignored){}}if(data==null)throw new IOException("OSM indisponível");JSONArray rows=data.getJSONArray("elements");for(int i=0;i<rows.length();i++){JSONObject o=rows.getJSONObject(i),t=o.optJSONObject("tags");if(t==null)continue;boolean bump=t.has("traffic_calming"),signal=t.optString("highway").equals("traffic_signals"),red=t.optString("enforcement").equals("traffic_signals")||t.optString("enforcement").equals("red_light");if(!bump&&!signal&&!red&&!t.optString("highway").equals("speed_camera")&&!t.optString("enforcement").equals("maxspeed"))continue;if(!o.has("lat")&&!bump)continue;JSONObject pos=o.has("lat")?o:o.optJSONObject("center");if(pos==null||!pos.has("lat"))continue;Event e=new Event("osm"+o.optString("type")+o.optLong("id"),bump?"lombada":signal?"semaforo":"radar",bump?"Lombada cadastrada":signal?"Semáforo · fase indisponível":red?"Radar de avanço de sinal":"Radar cadastrado","OpenStreetMap",pos.getDouble("lat"),pos.getDouble("lon"));try{e.limit=Double.parseDouble(t.optString("maxspeed"));}catch(Exception ignored){}mergeEvent(out,e);}}
 void loadAntt(GeoPoint p,ArrayList<Event> out)throws Exception{
 String url="https://dados.antt.gov.br/api/3/action/resource_show?id=a4b3efa6-55ae-408e-a583-52ddf34e4caf";
 String csvUrl=new JSONObject(get(url)).getJSONObject("result").getString("url");
 if(!csvUrl.startsWith("https://dados.antt.gov.br/"))throw new IOException("Fonte inválida");
 String[] rows=get(csvUrl).split("\\r?\\n");if(rows.length<2)return;
 String[] heads=rows[0].replace("\uFEFF","").split(";",-1);Map<String,Integer> col=new HashMap<>();for(int i=0;i<heads.length;i++)col.put(norm(heads[i].replace("\"","")),i);
 if(!col.containsKey("latitude")||!col.containsKey("longitude"))return;
 for(int i=1;i<rows.length;i++){String[] a=rows[i].split(";",-1);try{
 double lat=Double.parseDouble(csv(a,col,"latitude").replace(",",".")),lon=Double.parseDouble(csv(a,col,"longitude").replace(",","."));if(new GeoPoint(lat,lon).distanceToAsDouble(p)>65000)continue;
 String status=norm(csv(a,col,"situacao"));if(status.isEmpty())status=norm(csv(a,col,"situacao_do_radar"));if(status.isEmpty())status=norm(csv(a,col,"status"));boolean active=status.equals("ativo")||status.equals("ativa")||status.contains("operacional")&&!status.contains("inoperacional")||status.equals("em operacao");
 String label=active?"Radar de velocidade":"Radar ANTT cadastrado · situação não confirmada";
 Event e=new Event("antt"+lat+":"+lon,active?"radar":"historico",label,"ANTT · base publicada",lat,lon);String lim=csv(a,col,"velocidade_regulamentada");if(lim.isEmpty())lim=csv(a,col,"velocidade");try{e.limit=Double.parseDouble(lim.replace(",","."));}catch(Exception ignored){}mergeEvent(out,e);
 }catch(Exception ignored){}}
 }
 String csv(String[] row,Map<String,Integer> col,String key){Integer i=col.get(key);return i==null||i>=row.length?"":row[i].replace("\"","").trim();}
 void loadCariacica(GeoPoint p,ArrayList<Event> out)throws Exception{if(p.getLatitude()<-20.7||p.getLatitude()>-19.95||p.getLongitude()<-40.95||p.getLongitude()>-40.1)return;String raw=get("https://www.google.com/maps/d/kml?mid=1mhWiOBdxJtxmhcvUWExBEwiFSTBcU0A&forcekml=1");if(!raw.contains("Radares: Cariacica"))return;java.util.regex.Matcher m=java.util.regex.Pattern.compile("<Placemark>([\\s\\S]*?)</Placemark>").matcher(raw);while(m.find()){String b=m.group(1);java.util.regex.Matcher c=java.util.regex.Pattern.compile("<Point>[\\s\\S]*?<coordinates>([^<]+)</coordinates>").matcher(b);if(!c.find())continue;String[] v=c.group(1).trim().split(",");if(v.length<2)continue;double lon=Double.parseDouble(v[0]),lat=Double.parseDouble(v[1]);Event e=new Event("cariacica"+lat+":"+lon,"historico","Radar municipal cadastrado · situação atual não confirmada","Mapa municipal de Cariacica",lat,lon);mergeEvent(out,e);}}

